NEW_FOR_MANAGERS = ["company_update", "member_create", "member_delete"]


def grant_new_permissions(apps, schema_editor):
    User = apps.get_model("accounts", "User")
    for user in User.objects.filter(permissions__contains=["member_update"]):
        user.permissions = sorted(set(user.permissions) | set(NEW_FOR_MANAGERS))
        user.save(update_fields=["permissions"])


def revoke_new_permissions(apps, schema_editor):
    User = apps.get_model("accounts", "User")
    for user in User.objects.filter(permissions__overlap=NEW_FOR_MANAGERS):
        user.permissions = sorted(set(user.permissions) - set(NEW_FOR_MANAGERS))
        user.save(update_fields=["permissions"])


